INSERT INTO public.contract_clauses (id, company_id, created_by, name, category, language, content, variables, is_system, created_at, updated_at) VALUES
	('bf38d79b-55a1-4159-92e6-30422bf55cc1', NULL, NULL, 'Confidentiality', 'confidentiality', 'en', 'Each party shall keep confidential information received from the other party and use it only for the purposes of this agreement.', '[]', true, '2026-10-30 13:22:37.27363+00', '2026-10-30 13:22:37.27363+00'),
	('fea4026d-c484-42f0-a3ca-967b91699632', NULL, NULL, 'Kushtet e pagesës', 'payment', 'sq', 'Klienti do të paguajë {{contract.value}} {{contract.currency}} sipas planit të dakorduar të pagesës.', '["contract.value", "contract.currency"]', true, '2026-10-30 13:22:37.27363+00', '2026-10-30 13:22:37.27363+00'),
	('d1980554-3637-4e54-a532-34b9022a006f', NULL, NULL, 'Termination', 'termination', 'en', 'Either party may terminate this agreement by giving the notice period stated in the contract settings.', '[]', true, '2026-10-30 13:22:37.27363+00', '2026-10-30 13:22:37.27363+00'),
	('d13c2281-701e-4060-8780-65f6c2eb67b5', NULL, NULL, 'Payment terms', 'payment', 'en', 'The customer shall pay {{contract.value}} {{contract.currency}} according to the agreed payment schedule.', '["contract.value", "contract.currency"]', true, '2026-10-30 13:22:37.27363+00', '2026-10-30 13:22:37.27363+00'),
	('94dd90f5-3cff-4171-9cb9-ad89f74801a9', NULL, NULL, 'Përfundimi', 'termination', 'sq', 'Secila palë mund ta përfundojë këtë marrëveshje duke dhënë njoftimin e përcaktuar në cilësimet e kontratës.', '[]', true, '2026-10-30 13:22:37.27363+00', '2026-10-30 13:22:37.27363+00'),
	('532e9316-79e1-4afc-8162-20a978695c8c', NULL, NULL, 'Konfidencialiteti', 'confidentiality', 'sq', 'Secila palë do ta mbajë konfidencial informacionin e marrë nga pala tjetër dhe do ta përdorë vetëm për qëllimet e kësaj marrëveshjeje.', '[]', true, '2026-10-30 13:22:37.27363+00', '2026-10-30 13:22:37.27363+00');
